<?php
require_once __DIR__.'/../session_auth.php';require_once __DIR__.'/../db.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(!verifyWorkspaceClearance('etims_pdf_report.php')){echo "<script>window.location.href='../login.php?msg=err_unauthorized_access';</script>";exit;}
$sm=max(1,min(12,(int)($_REQUEST['report_month']??date('m'))));$sy=max(2024,min((int)date('Y'),(int)($_REQUEST['report_year']??date('Y'))));$period=sprintf('%04d-%02d',$sy,$sm);
$payment_totals="LEFT JOIN (SELECT order_id,SUM(CASE WHEN payment_status='completed' THEN amount ELSE 0 END)-SUM(CASE WHEN payment_status='refunded' THEN amount ELSE 0 END) net_paid,SUM(CASE WHEN payment_status='refunded' THEN amount ELSE 0 END) refunded FROM payments GROUP BY order_id) pay ON pay.order_id=o.id";
$included="DATE_FORMAT(o.created_at,'%Y-%m')=? AND LOWER(o.order_status)!='cancelled' AND COALESCE(pay.refunded,0)=0 AND COALESCE(pay.net_paid,0)+0.01>=o.total_amount";
$stmt=$conn->prepare("SELECT COUNT(*) c,COALESCE(SUM(o.total_amount),0) g,COALESCE(SUM(o.net_amount),0) n,COALESCE(SUM(o.vat_amount),0) v FROM orders o {$payment_totals} WHERE {$included}");$stmt->bind_param('s',$period);$stmt->execute();$totals=$stmt->get_result()->fetch_assoc();$stmt->close();
$cnt=(int)$totals['c'];$tg=(float)$totals['g'];$tn=(float)$totals['n'];$tt=(float)$totals['v'];
$counts=['paid'=>0,'processing'=>0,'delivered'=>0,'cancelled'=>0,'refunded'=>0];
$stmt=$conn->prepare("SELECT LOWER(o.order_status) order_status,COUNT(*) total,SUM(CASE WHEN COALESCE(pay.refunded,0)>0 THEN 1 ELSE 0 END) refunded_total FROM orders o {$payment_totals} WHERE DATE_FORMAT(o.created_at,'%Y-%m')=? GROUP BY LOWER(o.order_status)");$stmt->bind_param('s',$period);$stmt->execute();$res=$stmt->get_result();while($res&&$s=$res->fetch_assoc()){$counts[$s['order_status']]=(int)$s['total'];$counts['refunded']+=(int)$s['refunded_total'];}$stmt->close();
$stmt=$conn->prepare("SELECT o.id,o.net_amount,o.vat_amount,o.total_amount,o.applied_tax_rate,o.order_status,o.created_at,o.kra_pin,COALESCE(pay.net_paid,0) net_paid,COALESCE(pay.refunded,0) refunded FROM orders o {$payment_totals} WHERE DATE_FORMAT(o.created_at,'%Y-%m')=? ORDER BY o.id DESC");$stmt->bind_param('s',$period);$stmt->execute();$rows=$stmt->get_result();
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="monthly_tax_report_'.$period.'.csv"');echo chr(239).chr(187).chr(191);$out=fopen('php://output','w');fputcsv($out,['Invoice','Date','Buyer KRA PIN','Net','VAT Rate','VAT','Gross','Status','Treatment']);while($r=$rows->fetch_assoc()){$ok=strtolower($r['order_status'])!=='cancelled'&&(float)$r['refunded']==0&&(float)$r['net_paid']+0.01>=(float)$r['total_amount'];fputcsv($out,[$r['id'],$r['created_at'],$r['kra_pin']?:'Not provided',$r['net_amount'],$r['applied_tax_rate'],$r['vat_amount'],$r['total_amount'],$r['order_status'],$ok?'Included':'Excluded/Adjustment']);}fclose($out);exit;}
?>
<style>
