-table{width:100%;min-width:850px;border-collapse:collapse;font-size:12px}.tax-table th{padding:10px;background:#f1f5f9;color:#475569;text-align:left;text-transform:uppercase;font-size:10px}.tax-table td{padding:11px 10px;border-bottom:1px solid #e2e8f0}.money{white-space:nowrap;text-align:right}.tax-badge{font-size:9px;font-weight:900;text-transform:uppercase}.tax-badge.included{color:#15803d}.tax-badge.excluded{color:#dc2626}@media(max-width:900px){.tax-cards{grid-template-columns:1fr 1fr}.tax-btn.print{margin-left:0}}@media(max-width:600px){.tax-cards{grid-template-columns:1fr}.tax-filter>*{flex:1}.tax-filter h3{flex-basis:100%}.tax-head{flex-direction:column}}@media print{.sidebar,.navbar,.tax-filter{display:none!important}body,.main-content,#dynamic-workspace,.card{margin:0!important;padding:0!important;width:100%!important;background:#fff!important;border:0!important;box-shadow:none!important}.tax-sheet{max-width:none;margin:0!important;padding:20px!important;border:1px solid #000!important;box-shadow:none!important}.tax-table{display:table!important;min-width:0!important}.tax-table thead{display:table-header-group}.tax-table tr,.tax-cards,.tax-head{break-inside:avoid;page-break-inside:avoid}}
</style>
<section class="tax-report"><form class="tax-filter" action="etims_pdf_report.php" method="POST"><h3>Select Monthly Report Period</h3><select class="tax-select" name="report_month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$sm===$m?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor;?></select><select class="tax-select" name="report_year"><?php for($y=date('Y');$y>=2024;$y--):?><option value="<?=$y?>" <?=$sy===$y?'selected':''?>><?=$y?></option><?php endfor;?></select><button class="tax-btn" type="submit">Generate Report</button><a class="tax-btn csv" href="etims_pdf_report.php?report_month=<?=$sm?>&amp;report_year=<?=$sy?>&amp;export=csv">Export CSV</a><?php if($rows&&$rows->num_rows):?><button class="tax-btn print" type="button" onclick="window.print()">Print / Save PDF</button><?php endif;?></form>
<article class="tax-sheet"><header class="tax-head"><div><h1>ADONAK ELECTRONICS LTD</h1><p>Monthly Tax and Sales Statement</p></div><div style="text-align:right;font-size:12px;line-height:1.5"><strong>Reporting period:</strong> <?=date('F Y',mktime(0,0,0,$sm,1,$sy))?><br><strong>Trader PIN:</strong> <span class="tax-pin-warning">Not configured</span><br><strong>Generated:</strong> <?=date('d M Y, h:i A')?></div></header>
<div class="tax-cards"><article class="tax-card"><span>Included invoices</span><strong><?=$cnt?></strong></article><article class="tax-card"><span>Net turnover</span><strong>KES <?=number_format($tn,2)?></strong></article><article class="tax-card"><span>VAT total</span><strong>KES <?=number_format($tt,2)?></strong></article><article class="tax-card"><span>Gross sales</span><strong>KES <?=number_format($tg,2)?></strong></article></div>
<div class="tax-statuses"><span class="tax-status">Paid <?=$counts['paid']?></span><span class="tax-status">Processing <?=$counts['processing']?></span><span class="tax-status">Delivered <?=$counts['delivered']?></span><span class="tax-status danger">Cancelled <?=$counts['cancelled']?></span><span class="tax-status danger">Refunded <?=$counts['refunded']?></span></div>
<div class="tax-note">Totals include fully paid Processing, Paid, and Delivered orders. Cancelled, refunded, and underpaid orders remain visible below but are excluded from Net, VAT, and Gross totals.</div>
<div class="tax-table-wrap"><table class="tax-table"><thead><tr><th>Invoice</th><th>Date</th><th>Buyer KRA PIN</th><th class="money">Net</th><th class="money">VAT rate</th><th class="money">VAT</th><th class="money">Gross</th><th>Status</th><th>Treatment</th></tr></thead><tbody>
<?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):$ok=strtolower($r['order_status'])!=='cancelled'&&(float)$r['refunded']==0&&(float)$r['net_paid']+0.01>=(float)$r['total_amount'];?><tr><td><strong>#<?=(int)$r['id']?></strong></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($r['kra_pin']?:'Not provided')?></td><td class="money">KES <?=number_format($r['net_amount'],2)?></td><td class="money"><?=number_format($r['applied_tax_rate'],2)?>%</td><td class="money">KES <?=number_format($r['vat_amount'],2)?></td><td class="money"><strong>KES <?=number_format($r['total_amount'],2)?></strong></td><td><?=htmlspecialchars(ucfirst($r['order_status']))?></td><td><span class="tax-badge <?=$ok?'included':'excluded'?>"><?=$ok?'Included':'Excluded / adjustment'?></span></td></tr><?php endwhile;else:?><tr><td colspan="9" style="padding:35px;text-align:center;color:#94a3b8">No orders were recorded for this period.</td></tr><?php endif;?></tbody></table></div></article></section>